{
  "identity": {
    "name": "Ascending IT",
    "location": "Nampa, Idaho",
    "claims": [
      {
        "statement": "Ascending IT is physically located at 2128 N Devlin Way in Nampa, Idaho.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "2128 N Devlin Way, Nampa, ID 83687"
      },
      {
        "statement": "Ascending IT provides IT management and cybersecurity services across the Treasure Valley region.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Ascending IT delivers proactive IT management and built-in cybersecurity for small to medium businesses across the Treasure Valley."
      }
    ]
  },
  "industry": {
    "industry": "Information Technology / Managed Service Provider (MSP)",
    "activities": [
      "Managed IT support and 24/7 helpdesk monitoring",
      "Cybersecurity services including EDR, ransomware defense, and dark web monitoring",
      "Cloud and SaaS monitoring and automated email threat remediation",
      "Network, patch, and firewall management",
      "Backup, business continuity, and disaster recovery planning",
      "Virtual CIO (vCIO) consulting and compliance support"
    ],
    "claims": [
      {
        "statement": "Ascending IT delivers managed IT support services in the Boise area.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/managed-it-support-boise/",
        "quote": "Ascending IT delivers managed IT support in Boise that makes technology simple, secure, and reliable:"
      },
      {
        "statement": "Ascending IT provides proactive cybersecurity defenses against ransomware and phishing.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/cybersecurity-services-boise/",
        "quote": "From ransomware to phishing, we deliver proactive security that keeps your data safe, your team protected, and your business compliant."
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://ascending-it.com/",
    "claims": [
      {
        "statement": "Ascending IT's website positions the firm as a Boise IT company supporting small- to mid-sized organizations locally and nationwide.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/boise-it-company/",
        "quote": "Delivering small business IT support in Boise and nationwide, with scalable solutions and expertise mid-sized businesses need to stay secure and supported."
      },
      {
        "statement": "The company offers Free IT Assessments with multi-tiered service plans (Silver, Gold, Platinum).",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/",
        "quote": null
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The website footer reflects a copyright notice for Ascending-IT.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "© 2026 Ascending-IT | All Rights Reserved | Site by Modern Penguin"
      },
      {
        "statement": "The business operates from a physical street address in Nampa, Idaho, but does not display state entity filing or trade licensing numbers on its pages.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/",
        "quote": null
      }
    ],
    "limitations": "The website does not publish state business registry numbers, formal corporate formation types (LLC, Inc.), or professional trade license numbers."
  },
  "existingSoftware": [
    {
      "product": "ConnectBooster & IT Client Portal",
      "purpose": "Client payment processing and support ticket status tracking",
      "evidence": {
        "statement": "Ascending IT provides client self-service links for bill payment and support ticket viewing referencing ConnectBooster and IT Client Portal subdomains.",
        "label": "fact",
        "sourceUrl": "https://ascending-it.com/",
        "quote": "Make A Payment View Ticket Status"
      }
    },
    {
      "product": "WordPress & Divi Theme",
      "purpose": "Content management system and web page styling",
      "evidence": {
        "statement": "The website runs on WordPress with the Divi theme framework based on embedded script source paths.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/",
        "quote": null
      }
    },
    {
      "product": "Fluent Forms",
      "purpose": "Online form submission handling for contacts and assessment requests",
      "evidence": {
        "statement": "The site uses the Fluent Forms plugin to process inbound contact and IT assessment form submissions.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/it-support-boise/",
        "quote": null
      }
    },
    {
      "product": "Google reCAPTCHA",
      "purpose": "Spam prevention and bot mitigation on web forms",
      "evidence": {
        "statement": "Form submissions are protected by Google reCAPTCHA scripts embedded on contact and assessment pages.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/it-support-boise/",
        "quote": null
      }
    },
    {
      "product": "CookieYes",
      "purpose": "User cookie consent management",
      "evidence": {
        "statement": "The site loads CookieYes script libraries to manage visitor cookie preferences.",
        "label": "inference",
        "sourceUrl": "https://ascending-it.com/",
        "quote": null
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "Ascending IT is an IT managed service provider rather than a home-service contractor.",
      "label": "fact",
      "sourceUrl": "https://ascending-it.com/boise-it-company/",
      "quote": "As a Boise IT company, we help businesses take control of their technology, reduce costly downtime, and gain the confidence"
    },
    {
      "statement": "The company operates a 24/7 support desk and uses dedicated ticketing and billing portals.",
      "label": "fact",
      "sourceUrl": "https://ascending-it.com/it-support-boise/",
      "quote": "[redacted] Mon-Sun 24/7 Support 2128 N Devlin Way, Nampa, ID 83687"
    }
  ],
  "problems": [
    {
      "problem": "Target market mismatch: Ascending IT is a B2B managed IT services and cybersecurity firm, not an owner-led home-service contractor (HVAC, plumbing, electrical).",
      "label": "fact",
      "basis": "The site explicitly details managed IT, endpoint monitoring, network administration, and cybersecurity services for businesses, placing it outside ForgeX's home-service contractor focus."
    },
    {
      "problem": "The company already maintains internal technical capabilities and provides workflow, cybersecurity, and cloud monitoring solutions directly to clients.",
      "label": "inference",
      "basis": "Ascending IT advertises automated threat remediation, SaaS monitoring, and IT infrastructure administration, meaning they build and maintain IT solutions rather than needing outsourced contractor automation."
    },
    {
      "problem": "Potential lead routing or response delays between Fluent Forms submissions and backend MSP ticketing systems.",
      "label": "hypothesis",
      "basis": "Without internal backend access, it cannot be confirmed whether web form submissions automatically synchronize into their PSA/ticketing software."
    }
  ],
  "existingSolutions": [
    {
      "solution": "ConnectBooster and IT Client Portal",
      "addresses": "Client invoicing, payment automation, and support ticket management.",
      "alreadyOwned": true
    },
    {
      "solution": "Fluent Forms & WordPress Divi Platform",
      "addresses": "Lead capture and assessment request intake.",
      "alreadyOwned": true
    },
    {
      "solution": "MSP PSA/RMM Software Suite",
      "addresses": "Endpoint monitoring, automated patch deployment, and helpdesk dispatching.",
      "alreadyOwned": true
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because the company falls outside ForgeX's designated contractor target segment."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX automation solution is justified or recommended."
  },
  "humanReview": [],
  "risks": [
    {
      "type": "operational",
      "description": "Attempting to introduce trade-contractor automation workflows to an IT managed service provider would conflict with standard MSP ticketing and PSA workflows."
    },
    {
      "type": "security",
      "description": "Integrating external third-party automation tools into an MSP environment carries elevated security risk regarding managed client network credentials and configurations."
    },
    {
      "type": "compliance",
      "description": "MSPs frequently handle systems subject to regulatory compliance frameworks (HIPAA, PCI-DSS); unvetted automated pipeline tools could compromise compliance standards."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": []
  },
  "contacts": {
    "decisionMakerRoles": [
      "Owner / Founder",
      "Managing Director",
      "Operations / Service Desk Manager"
    ],
    "people": [],
    "channels": [
      {
        "kind": "email",
        "value": "[redacted]",
        "sourceUrl": "https://ascending-it.com/it-support-boise/"
      },
      {
        "kind": "phone",
        "value": "[redacted]",
        "sourceUrl": "https://ascending-it.com/it-support-boise/"
      },
      {
        "kind": "web form",
        "value": "https://ascending-it.com/it-support-boise/",
        "sourceUrl": "https://ascending-it.com/it-support-boise/"
      }
    ]
  },
  "discovery": {
    "questions": [
      "Does Ascending IT partner with or service residential home-service contractors (HVAC, plumbing, electrical) seeking workflow automation?",
      "What PSA or ticketing system currently integrates with your inbound Free IT Assessment web forms?"
    ],
    "outreachSubject": "",
    "outreachBody": ""
  },
  "evidence": {
    "sourcesUsed": [
      {
        "url": "https://ascending-it.com/",
        "usedFor": "Verified physical address, core positioning, service tiers, and customer portal links"
      },
      {
        "url": "https://ascending-it.com/boise-it-company/",
        "usedFor": "Company background, values, mission, and B2B target market details"
      },
      {
        "url": "https://ascending-it.com/it-support-boise/",
        "usedFor": "Contact methods (phone, email, web form), operating hours, and location verification"
      },
      {
        "url": "https://ascending-it.com/managed-it-support-boise/",
        "usedFor": "Managed IT service breakdown, pricing model details, and FAQ analysis"
      },
      {
        "url": "https://ascending-it.com/cybersecurity-services-boise/",
        "usedFor": "Cybersecurity service catalog and capabilities assessment"
      },
      {
        "url": "https://ascending-it.com/free-it-assessment-boise/",
        "usedFor": "Assessment process overview and turnaround commitments"
      },
      {
